var CASES=[{"id":1,"title":"از سازمان کوچک و غیررسمی تا سازمان حرفه‌ای","concept":"تغییر هنجارهای کاری","evidence":"وقتی کسی روش مشترک را رعایت می‌کند چه واکنشی می‌گیرد؟ وقتی با رابطه شخصی کار را جلو می‌برد چه امتیازی می‌گیرد؟ یک نمونه مخالف هم پیدا کنید.","variants":{"managers":{"problem":"در یک سناریوی آموزشی، مدیر ستاد با تماس تلفنی درخواست خودرو را تأیید می‌کند؛ سایت دیگر همان درخواست را با پیام شخصی جلو می‌برد. با افزایش مأموریت‌ها، ظرفیت یک خودرو به دو کار وعده داده می‌شود. هر مدیر می‌گوید روش قبلی سریع‌تر بود؛ اما کسی تصویر مشترکی از تعهدات ندارد.","analysis":["باور احتمالی: «حرفه‌ای‌شدن یعنی از دست‌دادن صمیمیت و سرعت.» این باور می‌تواند مقاومت در برابر روش مشترک را توضیح دهد؛ وجود آن را از افراد بپرسید.","افراد باتجربه ممکن است احساس کنند اعتبار و تجربه‌شان نادیده گرفته می‌شود؛ کنارگذاشتن آنان مقاومت را بیشتر می‌کند.","اگر مدیر خودش استثنا می‌سازد، پیام واقعی این است که رابطه شخصی هنوز از توافق جمعی مؤثرتر است."],"lesson":"تغییر رفتار زمانی ماندگارتر می‌شود که افراد دلیل تغییر را بفهمند، در شکل‌گیری آن سهم داشته باشند و مدیر هم آن را رعایت کند.","note":"تجربه گذشته را به رسمیت بشناسید؛ درباره عادت‌های نامناسب گذشته هم گفت‌وگو کنید.","solution":["از مدیران و کارکنان باتجربه بپرسید: «از روش قبلی چه چیزی را حفظ کنیم و چه چیزی امروز به دیگران آسیب می‌زند؟»","دو رفتار مشترک انتخاب کنید؛ مثلاً پیش از قول‌دادن هماهنگ کنیم و تغییر تصمیم را به فرد درگیر خبر بدهیم.","خودتان نخستین اجراکننده باشید. اگر استثنا ساختید، دلیلش را توضیح دهید و مسئولیت اثر آن را بپذیرید.","در جلسه بعد یک نمونه رعایت توافق را مشخصاً قدردانی کنید و بپرسید چه چیزی اجرای آن را سخت کرده است."],"questions":["مقاومت در برابر تغییر از تنبلی می‌آید یا ترس از ازدست‌دادن جایگاه؟ چه شاهدی داریم؟","کدام رفتار خود ما، روش غیررسمی گذشته را دوباره تقویت می‌کند؟"],"dialogue":"تجربه شما برای ما مهم است؛ بیایید ببینیم چطور آن را به روشی تبدیل کنیم که همه بتوانند به آن تکیه کنند."},"hq":{"problem":"دو سایت درخواست قطعه مشابه می‌فرستند؛ یکی تلفنی و دیگری در یک پیام گروهی. شما درخواست دوم را ثبت می‌کنید و تصور می‌کنید اولی را همکارتان انجام داده است. سایت اول پیگیری می‌کند و هیچ‌کس شماره درخواست یا آخرین وضعیت را ندارد.","analysis":["ممکن است عادت کرده باشیم فقط درخواست افراد آشنا را جدی بگیریم؛ در نتیجه همکاری به رابطه شخصی وابسته می‌شود.","وقتی انتظار روشن نیست، هر نفر «درست انجام‌دادن کار» را به شکل خودش معنی می‌کند.","اگر پیگیری محترمانه با برچسب سخت‌گیری روبه‌رو شود، کارکنان کم‌کم از روشن‌کردن تعهدها صرف‌نظر می‌کنند."],"lesson":"حرفه‌ای‌بودن یعنی دیگران بتوانند رفتار ما را پیش‌بینی کنند و فقط به آشنایی شخصی وابسته نباشند.","note":"صمیمی بمانید، اما روشن حرف بزنید و به توافق پایبند باشید.","solution":["به همکار بگویید از درخواست او چه فهمیده‌اید و بپرسید چه نتیجه‌ای انتظار دارد.","به جای «احتمالاً یکی انجام می‌دهد»، روشن کنید شما چه بخشی را می‌پذیرید و برای بخش دیگر از چه کسی کمک می‌خواهید.","روش روشن و محترمانه را برای درخواست‌کننده آشنا و ناآشنا یکسان به کار ببرید.","آخر هفته یک مورد را مرور کنید که گفت‌وگوی روشن، سوءتفاهم را کمتر کرده است."],"questions":["کجا رابطه شخصی جای اعتماد به روش مشترک را گرفته است؟","چه رفتاری باعث می‌شود همکار تازه‌وارد هم بتواند روی ما حساب کند؟"],"dialogue":"برای اینکه برداشت‌مان یکی باشد، اجازه بدهید بگویم من چه کاری را تا چه زمانی قبول می‌کنم."},"operations":{"problem":"فرض کنید دیروز زمان حرکت را تلفنی گفته‌اند و امروز در پیام گروهی زمان دیگری دیده‌اید. همکار قدیمی می‌گوید: «همان ساعت دیروز برو.» شما نمی‌دانید کدام برنامه معتبر است و ممکن است به محل بارگیری برسید اما نوبت شما نباشد.","analysis":["وقتی همکار قدیمی می‌گوید «همیشه همین‌طور بوده»، ممکن است برای مخالفت محترمانه احساس راحتی نکنیم.","ترس از کم‌تجربه دیده‌شدن می‌تواند مانع پرسیدن شود.","روش مشترک زمانی پذیرفته می‌شود که سرپرست و همکار باتجربه هم به آن پایبند باشند."],"lesson":"پرسیدن و روشن‌کردن کار، نشانه مسئولیت‌پذیری است.","note":"به تجربه همکار احترام بگذارید؛ ابهام خودتان را هم پنهان نکنید.","solution":["بگویید چه چیز را متوجه نشده‌اید؛ از حدس‌زدن خجالت نکشید.","اگر روش تازه‌ای اعلام شده، دلیلش را از مسئول بپرسید و آن را با برداشت خود بازگو کنید.","همکار تازه‌وارد را برای سؤال‌پرسیدن مسخره نکنید و در فهم کار کمکش کنید.","در پایان شیفت یک ابهام را که با پرسیدن حل شد، با گروه مرور کنید."],"questions":["چرا گاهی سؤال خودمان را نمی‌پرسیم؟","همکار باتجربه چگونه می‌تواند یادگرفتن را برای دیگران آسان کند؟"],"dialogue":"می‌خواهم درست انجام بدهم؛ لطفاً روشن کنید الان از من چه انتظاری دارید."}},"theory":{"name":"مدل فرهنگ سازمانی ادگار شاین","explanation":"شاین میان رفتارهای آشکار، ارزش‌های اعلام‌شده و باورهای عمیق مشترک تفاوت می‌گذارد. برای تغییر فرهنگ باید باور پشت رفتار را هم شناخت؛ نوشتن قاعده به‌تنهایی کافی نیست.","source":"schein"}},{"id":2,"title":"دور زدن مدیر و مسیرهای غیررسمی","concept":"وضوح نقش و اعتماد به مدیر","evidence":"فرد چرا از مدیر مستقیم عبور کرده است: بی‌پاسخی، بی‌اعتمادی، ترس، عادت یا گرفتن امتیاز؟ پاسخ را از هر دو طرف بشنوید.","variants":{"managers":{"problem":"مدیر سایت برای تأمین فوری یک خدمت، مستقیماً از مقام بالاتر قول می‌گیرد. مدیر مسئول بودجه بعداً متوجه تعهد می‌شود و می‌گوید امکان اجرای آن نیست. در سوی دیگر، کارمندی درباره رفتار نامناسب مدیر مستقیمش فقط به همان مدیر ارجاع داده می‌شود و سکوت می‌کند.","analysis":["اگر مدیر مستقیم گوش نمی‌دهد یا پاسخ را عقب می‌اندازد، کارکنان ممکن است مسیر دیگری را مؤثرتر بدانند.","اگر مقام بالاتر بدون شنیدن مسئول مربوط، قول تازه بدهد، ناخواسته عبور از نقش‌ها را تشویق می‌کند.","ترس از مدیر و گزارش رفتار نامناسب را با امتیازگرفتن از رابطه شخصی یکسان نبینید؛ اولی به امکان بیان امن نیاز دارد."],"lesson":"اعتبار مدیر مستقیم فقط از عنوان او نمی‌آید؛ از پاسخ‌گویی، انصاف و شنیدن مسئله ساخته می‌شود.","note":"برای حفظ جایگاه مدیر، صدای کارکنان را نبندید.","solution":["پیش از سرزنش فرد بپرسید: «چه شد که احساس کردی از این راه باید جلو بروی؟»","مدیر مستقیم مسئله را بشنود و زمان پاسخ روشنی بدهد؛ مقام بالاتر هم تصمیم ناسازگار و پنهانی نسازد.","درباره انتظار از نقش‌ها و شرایط ارجاع، با مثال روزمره توافق کنید؛ گزارش خطر یا آزار نباید به اجازه فرد مورد گزارش وابسته باشد.","در پیگیری بعدی بپرسید آیا اعتماد به پاسخ‌گویی بیشتر شده است؛ فقط تعداد مراجعه به مدیر بالاتر را نسنجید."],"questions":["آیا رفتار خود مدیر، مراجعه از مسیر غیررسمی را تقویت کرده است؟","چگونه هم نقش مدیر مستقیم را حفظ کنیم و هم صدای کارکنان را بشنویم؟"],"dialogue":"می‌خواهم قبل از قضاوت بفهمم چه چیزی باعث شد احساس کنی از مسیر معمول پاسخ نمی‌گیری."},"hq":{"problem":"شما منتظر تأیید درخواست یک سایت هستید. درخواست‌کننده می‌گوید: «با مدیر بالاتر هماهنگ کردم، ثبت لازم نیست.» همکار دیگری برای گزارش برخورد توهین‌آمیز مدیرش از شما راهنمایی می‌خواهد. هر دو موضوع فوری به نظر می‌رسند، اما مسیرشان یکسان نیست.","analysis":["وقتی پاسخ روشن نمی‌گیریم، ممکن است به رابطه شخصی متوسل شویم و مسئولیت دیگران را نادیده بگیریم.","گاهی هم از ناراحت‌شدن مدیر می‌ترسیم و اختلاف دستورها را پنهان می‌کنیم.","پیام‌های متفاوت مدیران، انتخاب را برای کارمند دشوار می‌کند؛ کارمند نباید مسئول پنهان این تعارض شود."],"lesson":"به‌جای دورزدن یا سکوت، دلیل درخواست و تعارض انتظارها را روشن و محترمانه بیان کنید.","note":"برای گرفتن پاسخ، مسئله را توضیح دهید؛ از نام افراد برای فشار استفاده نکنید.","solution":["به مدیر مستقیم بگویید چه کمکی لازم دارید و تأخیر چه اثری بر کار دیگران دارد.","اگر دو انتظار ناسازگار دارید، هر دو را بدون جانبداری بازگو و تعیین تکلیف بخواهید.","در ارجاع به سطح دیگر، علت را شفاف بگویید؛ برای نگرانی درباره رفتار نامناسب از مسیر مستقل کمک بگیرید.","بعد از تصمیم، نتیجه را به افراد مرتبط برگردانید تا کسی احساس کنارگذاشته‌شدن نکند."],"questions":["چه چیزی مانع گفت‌وگوی مستقیم ما با مسئول مربوط می‌شود؟","تفاوت پیگیری مسئولانه با گرفتن امتیاز از رابطه چیست؟"],"dialogue":"از من دو کار ناسازگار خواسته شده؛ برای اینکه مسئولانه عمل کنم، به روشن‌شدن انتظار نهایی نیاز دارم."},"operations":{"problem":"در برنامه شما یک مأموریت مشخص شده؛ فردی از واحد دیگر تماس می‌گیرد و می‌گوید اول کار او را انجام دهید. هم‌زمان ممکن است درباره یک خطر جدی از مسئول مستقیم پاسخ نگیرید. آیا هر بار باید از همان مسیر قبلی منتظر بمانید؟","analysis":["وقتی دو نفر دستور متفاوت می‌دهند، ممکن است بترسیم با پرسیدن یکی را ناراحت کنیم.","آشنایی با یک مسئول می‌تواند ما را به گرفتن امتیاز شخصی عادت دهد.","اگر سؤال با تندی پاسخ داده شود، افراد دفعه بعد ابهام را پنهان می‌کنند."],"lesson":"ابهام را محترمانه بگویید و مسئول روشن‌شدن انتظار را مشخص بخواهید.","note":"سکوت در برابر دستور متعارض، مشکل را حل نمی‌کند.","solution":["بگویید دو پیام متفاوت دریافت کرده‌اید؛ درباره نیت هیچ‌کس قضاوت نکنید.","از مسئول بخواهید انتظار نهایی را روشن کند و بگویید شما چه فهمیده‌اید.","برای امتیازگرفتن از آشنایی استفاده نکنید؛ همان انتظار مشترک را برای همه بپذیرید.","اگر از طرح نگرانی درباره مسئول مستقیم می‌ترسید، از مسیر مستقل معرفی‌شده کمک بخواهید."],"questions":["وقتی دو نفر دو دستور می‌دهند، چه احساسی پیدا می‌کنید؟","چه واکنشی از سرپرست باعث می‌شود دفعه بعد راحت‌تر سؤال بپرسید؟"],"dialogue":"قصد مخالفت ندارم؛ دو انتظار متفاوت شنیده‌ام و می‌خواهم درست عمل کنم."}},"theory":{"name":"ابهام و تعارض نقش؛ ریزو، هاوس و لیرتزمن","explanation":"ابهام نقش یعنی فرد انتظارها و حدود مسئولیتش را به‌خوبی نمی‌داند. تعارض نقش یعنی با انتظارهای ناسازگار روبه‌روست. مسئله همیشه بی‌انضباطی فرد نیست؛ پیام‌های مدیران هم باید بررسی شوند.","source":"role"}},{"id":3,"title":"قانون‌مداری و صمیمیت حرفه‌ای","concept":"عدالت سازمانی و مرز حرفه‌ای","evidence":"آیا فرد دلیل تصمیم را شنیده، فرصت توضیح داشته و با احترام با او برخورد شده است؟ درخواست‌های مشابه را بدون نام مقایسه کنید.","variants":{"managers":{"problem":"یک سرپرست می‌گوید برای حفظ رابطه با راننده باتجربه، نوبت مأموریت او را خارج از قاعده جابه‌جا کرده است. دیگری برای همان درخواست رد می‌شود. در ستاد هم یک همکار آشنا کارش را زودتر پیش می‌برد و کارکنان عدالت تصمیم‌ها را زیر سؤال می‌برند.","analysis":["دوستی و سابقه همکاری ممکن است ناآگاهانه روی قضاوت مدیر اثر بگذارد.","کارکنان فقط نتیجه را مقایسه نمی‌کنند؛ نگاه می‌کنند آیا فرصت شنیده‌شدن و توضیح تصمیم برای همه وجود دارد.","استثنای توضیح‌داده‌نشده، حتی با نیت خوب، می‌تواند به احساس تبعیض تبدیل شود."],"lesson":"مدیر منصف، هم دلیل قابل دفاع دارد، هم به افراد فرصت بیان می‌دهد و هم حرمت آنان را حفظ می‌کند.","note":"صمیمیت را حفظ کنید؛ معیار تصمیم را شخصی نکنید.","solution":["پیش از تصمیم از خود بپرسید: «اگر این فرد دوست من نبود، همین انتخاب را می‌کردم؟»","دیدگاه افراد اثرپذیر را بشنوید و معیار کاری تصمیم را با زبان روشن توضیح دهید.","در پاسخ منفی، رفتار محترمانه را حفظ کنید؛ مخالفت را به بی‌وفایی تعبیر نکنید.","در جلسه بعد از تیم درباره یک تصمیم مشخص بازخورد بخواهید: چه چیزی منصفانه یا مبهم بود؟"],"questions":["کدام بخش تصمیم ما ممکن است برای دیگران تبعیض‌آمیز دیده شود؟","چگونه تفاوت شرایط را توضیح می‌دهیم بدون اینکه اطلاعات خصوصی کسی را افشا کنیم؟"],"dialogue":"می‌دانم این نتیجه برای شما خوشایند نیست؛ اجازه بدهید معیار تصمیم را توضیح بدهم و دیدگاه شما را هم بشنوم."},"hq":{"problem":"همکارتان می‌گوید صورت‌هزینه یک آشنا را زودتر بررسی کنید، در حالی که درخواست‌های کامل دیگری در صف‌اند. می‌خواهید رابطه خوبی داشته باشید، اما دیگران از شما درباره نوبت رسیدگی توضیح می‌خواهند.","analysis":["رودربایستی می‌تواند باعث شود خواسته همکار نزدیک را زودتر از دیگران جدی بگیریم.","وقتی دلیل تفاوت رفتار روشن نیست، دیگران آن را به رابطه شخصی نسبت می‌دهند.","پاسخ خشک و بی‌احترام هم می‌تواند احساس بی‌عدالتی بسازد، حتی اگر ترتیب رسیدگی درست باشد."],"lesson":"رفتار منصفانه یعنی معیار مشترک، توضیح روشن و احترام در پاسخ‌گویی.","note":"برای حفظ دوستی، حق همکار دیگر را نادیده نگیرید.","solution":["درخواست فرد آشنا را با همان دقتی بشنوید که درخواست دیگران را می‌شنوید.","اگر نمی‌توانید امتیاز ویژه بدهید، محترمانه دلیل را توضیح دهید و کمک ممکن را پیشنهاد کنید.","درباره فوریت واقعی سؤال کنید؛ آشنایی را دلیل فوریت ندانید.","یک بار رفتار خود را از نگاه همکار تازه‌وارد مرور کنید: آیا او هم همین دسترسی و احترام را دارد؟"],"questions":["کجا رودربایستی تصمیم حرفه‌ای ما را تغییر می‌دهد؟","چطور هم محترمانه پاسخ منفی بدهیم و هم رابطه را حفظ کنیم؟"],"dialogue":"دوست دارم کمک کنم؛ بیایید همان معیار مشترک را رعایت کنیم و ببینیم چه کمکی در چارچوب آن ممکن است."},"operations":{"problem":"یکی از همکاران قدیمی می‌گوید: «با نگهبانی آشنا هستم؛ لازم نیست منتظر نوبت بمانیم.» شما می‌خواهید رابطه خوب بماند، اما می‌بینید دیگران طبق برنامه منتظرند. قاعده سایت هم مسیر مشخصی دارد.","analysis":["برای پذیرفته‌شدن در جمع ممکن است از امتیاز ویژه همکاران آشنا حمایت کنیم.","اگر نوبت و برخورد برای افراد متفاوت باشد، احساس بی‌عدالتی و دلخوری بالا می‌رود.","طعنه و دعوا معمولاً فرصت شنیدن دلیل واقعی را کمتر می‌کند."],"lesson":"از حق خود و دیگران با احترام دفاع کنید.","note":"رابطه خوب نباید به امتیاز ناعادلانه تبدیل شود.","solution":["قبل از اعتراض، دلیل تفاوت را از مسئول بپرسید؛ ممکن است شرایطی باشد که نمی‌دانید.","خواسته خود را روشن بگویید و از توهین یا متهم‌کردن خودداری کنید.","اگر نوبت ویژه‌ای به شما پیشنهاد شد، بپرسید آیا برای همه در همین شرایط امکان‌پذیر است.","با همکار تازه‌وارد همان‌قدر محترمانه برخورد کنید که با همکار قدیمی."],"questions":["کدام رفتار باعث می‌شود احساس کنید با شما منصفانه برخورد شده است؟","چطور بدون دعوا درباره نوبت خود سؤال می‌کنید؟"],"dialogue":"می‌خواهم دلیل این تفاوت را بدانم؛ انتظارم این است که در شرایط مشابه با همه یکسان برخورد شود."}},"theory":{"name":"چهار بُعد عدالت سازمانی؛ کالکویت","explanation":"عدالت فقط سهم و پاداش نیست. منصفانه‌بودن روش تصمیم، برخورد محترمانه و توضیح صادقانه هم اهمیت دارند. ممکن است نتیجه برای فرد خوشایند نباشد، اما روش و برخورد را منصفانه بداند.","source":"justice"}},{"id":4,"title":"قول می‌دهیم؛ اما آیا انجام می‌دهیم؟","concept":"تعهد روشن و قابل اتکا بودن","evidence":"آیا فرد واقعاً تعهد را پذیرفته یا برای راضی‌کردن مدیر قول داده است؟ آیا می‌تواند بدون تحقیر درباره مانع و تأخیر حرف بزند؟","variants":{"managers":{"problem":"در جلسه گفته می‌شود قطعه مورد نیاز ناوگان «تا فردا جور می‌شود». سایت بر اساس همین قول برنامه می‌چیند؛ اما خرید منتظر مشخصات فنی و مالی منتظر تأیید است. روز بعد خودرو همچنان آماده نیست و هر واحد می‌گوید کار خودش را انجام داده است.","analysis":["ممکن است فرهنگ جلسه به‌گونه‌ای باشد که گفتن «فعلاً نمی‌توانم قول قطعی بدهم» ضعف تلقی شود.","مدیر با استقبال از وعده‌های خوش‌بینانه و واکنش تند به خبر بد، قول بی‌پشتوانه را تقویت می‌کند.","وقتی بازخورد فقط هنگام شکست داده می‌شود، موانع زودهنگام پنهان می‌مانند."],"lesson":"تعهد واقعی از گفت‌وگوی صادقانه درباره انتظار و امکان انجام می‌آید؛ موافقت ظاهری کافی نیست.","note":"صداقت درباره محدودیت را بیشتر از قول خوشایند تشویق کنید.","solution":["بعد از هر قول بپرسید: «این موعد را با چه اطمینانی می‌پذیری و چه کمکی لازم داری؟»","روشن بگویید اعلام زودهنگام مانع، رفتار مسئولانه است؛ خودتان هم تأخیر تعهدتان را زود اعلام کنید.","در پیگیری، ابتدا واقعیت و مانع را بشنوید و سپس درباره مسئولیت و قدم بعدی توافق کنید.","از پیگیری تا نتیجه و خبررسانی صادقانه قدردانی کنید؛ فقط نتیجه نهایی را نبینید."],"questions":["چه واکنشی از ما باعث قول‌دادن برای راضی‌کردن مدیر می‌شود؟","تعهد واقعی چه تفاوتی با موافقت در جلسه دارد؟"],"dialogue":"قولی می‌خواهم که بتوانی پشت آن بایستی؛ اگر مانعی هست الان درباره‌اش حرف بزنیم."},"hq":{"problem":"به سایت می‌گویید مدارک مأموریت امروز آماده می‌شود. هنگام پایان کار متوجه می‌شوید یک تأیید نرسیده؛ تصور می‌کنید سایت خودش متوجه تأخیر می‌شود. صبح بعد راننده برای دریافت مدارک مراجعه می‌کند و آماده نیست.","analysis":["گاهی از ترس ناراحت‌شدن دیگران به کاری قول می‌دهیم که هنوز امکانش روشن نیست.","ممکن است تصور کنیم اعلام تأخیر اعتبار ما را کم می‌کند؛ در حالی که بی‌خبرگذاشتن دیگران اعتماد را فرسوده می‌کند.","پاس‌دادن درخواست بدون پیگیری، احساس انجام وظیفه می‌دهد ولی نیاز همکار را بی‌پاسخ می‌گذارد."],"lesson":"قابل اتکا بودن یعنی قول سنجیده، خبررسانی صادقانه و پیگیری مسئولانه.","note":"برای خوشحال‌کردن لحظه‌ای دیگران، انتظار نادرست نسازید.","solution":["قبل از قول‌دادن، بگویید چه چیزی در اختیار شماست و چه چیزی به کمک دیگری بستگی دارد.","انتظار طرف مقابل را با زبان خودتان بازگو کنید تا توافق واقعی شکل بگیرد.","به محض دیدن مانع، خبر بدهید و پیشنهاد قدم بعدی را مطرح کنید؛ منتظر پیگیری طرف مقابل نمانید.","بعد از انجام، بپرسید آیا نتیجه نیاز او را پاسخ داده است."],"questions":["چه چیزی باعث می‌شود بیش از توان واقعی خود قول بدهیم؟","چگونه بدون بهانه‌تراشی، مانع و قدم بعدی را توضیح می‌دهیم؟"],"dialogue":"این بخش را می‌پذیرم؛ برای بخش دیگر هنوز تأیید ندارم و نمی‌خواهم به شما قول نادرست بدهم."},"operations":{"problem":"پایان شیفت می‌گویید: «موضوع نقص خودرو را به شیفت بعد می‌گویم.» بعد عجله می‌کنید و می‌روید. همکار بعدی از موضوع خبر ندارد و فکر می‌کند خودرو طبق روال آماده است.","analysis":["ممکن است برای پایان سریع گفت‌وگو بگوییم «چشم» در حالی که انتظار را کامل نفهمیده‌ایم.","ترس از سرزنش، خبررسانی درباره انجام‌نشدن کار را عقب می‌اندازد.","اگر فقط گفتن مهم باشد و پیگیری دیده نشود، قول‌دادن از انجام‌دادن آسان‌تر می‌شود."],"lesson":"چیزی را قبول کنید که فهمیده‌اید و می‌توانید انجام دهید؛ اگر مانع پیش آمد زود بگویید.","note":"«چشم» بدون فهم کار، تعهد روشن نیست.","solution":["بگویید از کار خواسته‌شده چه فهمیده‌اید و هر ابهام را همان موقع بپرسید.","اگر نمی‌توانید قول بدهید، دلیل واقعی را محترمانه بگویید و کمک بخواهید.","وقتی مانعی پیش آمد، خودتان خبر بدهید؛ منتظر نمانید کسی از شما بپرسد.","بعد از تحویل کار از نفر بعدی بپرسید آیا موضوع برایش روشن است."],"questions":["چرا گاهی «چشم» می‌گوییم ولی کار را کامل نفهمیده‌ایم؟","اگر قول شما انجام نشود، چه رفتاری اعتماد را بهتر حفظ می‌کند؟"],"dialogue":"قبول می‌کنم این بخش را انجام بدهم؛ اگر به مانع بخورم، قبل از موعد به شما خبر می‌دهم."}},"theory":{"name":"نظریه هدف‌گذاری لاک و لاتام","explanation":"هدف روشن و چالش‌برانگیز، همراه با پذیرش هدف، توانایی لازم و بازخورد، می‌تواند تلاش را جهت بدهد. گفتن «تمام سعی‌ات را بکن» جای روشن‌کردن انتظار و فراهم‌کردن امکان انجام را نمی‌گیرد.","source":"goals"}},{"id":5,"title":"همکاری مدیرانی که با هم اختلاف دارند","concept":"اختلاف سازنده و هدف مشترک","evidence":"گفت‌وگوها درباره مسئله‌اند یا شخصیت طرف مقابل؟ چه رفتارهایی اختلاف مدیران را به کارکنان منتقل می‌کند؟","variants":{"managers":{"problem":"مدیر عملیات خواهان آماده‌سازی سریع خودروست و مدیر پشتیبانی می‌گوید اعتبار و قطعه در دسترس نیست. اختلاف به پیام‌های کنایه‌آمیز تبدیل می‌شود و کارکنان هر واحد از پاسخ به واحد دیگر طفره می‌روند. مسئله خودرو حل نشده، اما دو جبهه شکل گرفته است.","analysis":["ممکن است اختلاف درباره زمان و منابع به رقابت بر سر اعتبار و برنده‌شدن تبدیل شده باشد.","ذهن‌خوانی‌هایی مثل «او نمی‌خواهد کار پیش برود» شنیدن محدودیت واقعی طرف مقابل را دشوار می‌کند.","کنایه مدیر به کارکنان یاد می‌دهد که وفاداری به واحد خود را با همکاری‌نکردن نشان دهند."],"lesson":"اختلاف نظر را به موضوع کار محدود کنید و همکاری را به دوست‌داشتن یکدیگر وابسته نکنید.","note":"در جمع، مدیر دیگر را تضعیف نکنید؛ اختلاف را مستقیم و محترمانه مطرح کنید.","solution":["با طرف مقابل جداگانه گفت‌وگو کنید و یک رفتار مشخص و اثرش را توضیح دهید؛ از «همیشه» و «هیچ‌وقت» استفاده نکنید.","پیش از دفاع از نظر خود، برداشتتان از نگرانی او را بازگو کنید و از درستی آن بپرسید.","هدف مشترک را روشن کنید و بر یک اقدام همکاری توافق کنید، حتی اگر همه اختلاف‌ها حل نشده‌اند.","به تیم‌ها پیام مشترک بدهید که همکاری ادامه دارد و هفته بعد اثر توافق را مرور کنید."],"questions":["آیا دنبال حل مسئله‌ایم یا اثبات اینکه حق با ماست؟","چه رفتاری از خود ما، طرف مقابل را دفاعی می‌کند؟"],"dialogue":"نگرانی من اثر این تأخیر بر کار مشترک است؛ می‌خواهم محدودیت شما را هم بفهمم تا راهی پیدا کنیم."},"hq":{"problem":"به شما گفته می‌شود: «تا آن واحد جواب ما را ندهد، کارشان را انجام نده.» درخواست یک سایت به همکاری هر دو واحد وابسته است و شما بین وفاداری به مدیر و پاسخ به نیاز کار گیر کرده‌اید.","analysis":["وفاداری به مدیر ممکن است با جانبداری و انتقال کنایه اشتباه شود.","وقتی طرف مقابل را «همیشه مانع» می‌بینیم، پاسخ عادی او را هم منفی تفسیر می‌کنیم.","همکاری‌نکردن متقابل، اختلاف بالادستی را به عادت روزمره واحدها تبدیل می‌کند."],"lesson":"به واحد خود متعهد باشید و در عین حال به حل کار مشترک کمک کنید.","note":"پیام‌رسان توهین و کنایه نشوید.","solution":["هنگام تماس با همکار واحد دیگر، موضوع مشخص و نیاز کاری را مطرح کنید؛ سابقه دعوا را وارد نکنید.","اگر پاسخ او را مبهم یا تند فهمیدید، پیش از واکنش بپرسید منظورش چیست.","بخش در اختیار خود را مسئولانه انجام دهید و مانع تصمیم را بی‌طرفانه به سرپرست بگویید.","در جمع از برچسب‌هایی مثل «آن‌ها هیچ‌وقت همکاری نمی‌کنند» فاصله بگیرید و یک رفتار مشخص را توضیح دهید."],"questions":["چگونه بدون جانبداری از اختلاف مدیران، به مدیر خود وفادار بمانیم؟","کدام پیش‌داوری ما درباره واحد مقابل نیاز به بازبینی دارد؟"],"dialogue":"می‌خواهم روی همین درخواست تمرکز کنیم؛ چه چیزی از طرف من کمک می‌کند کار مشترک جلو برود؟"},"operations":{"problem":"دو مسئول درباره محل انجام کار اختلاف دارند. هر کدام می‌گوید دستور خودش را اجرا کنید و از دیگری انتقاد می‌کند. شما نمی‌دانید کار کجا انجام شود و نگرانید هر انتخابی باعث سرزنش شود.","analysis":["ممکن است احساس کنیم باید در دعوای دو مسئول طرف یکی را بگیریم.","نقل حرف‌ها و کنایه‌ها اختلاف را بیشتر می‌کند و اعتماد بین گروه‌ها را کم می‌کند.","ترس از سرزنش می‌تواند ما را از روشن‌کردن دستورهای متفاوت بازدارد."],"lesson":"روی کار و انتظار روشن تمرکز کنید؛ وارد رقابت و بدگویی گروه‌ها نشوید.","note":"همکاری یعنی کمک به حل مسئله، نه پخش‌کردن اختلاف.","solution":["وقتی از مسئول دیگری انتقاد می‌شود، گفت‌وگو را به کار مشخص برگردانید.","دو انتظار متفاوت را بدون اتهام بازگو کنید و روشن‌شدن کار را بخواهید.","از نقل کنایه و شایعه بین دو گروه خودداری کنید.","اگر با همکار اختلاف دارید، درباره رفتار و اثرش صحبت کنید و یک توافق کوچک برای همکاری بسازید."],"questions":["چه رفتاری از ما دعوای دو گروه را بزرگ‌تر می‌کند؟","چگونه می‌توانیم بدون طرف‌گرفتن، کمک‌کننده باشیم؟"],"dialogue":"من می‌خواهم کار درست پیش برود؛ لطفاً انتظار روشن را بگویید تا وارد اختلاف نشوم."}},"theory":{"name":"نظریه همکاری و رقابت مورتون دویچ","explanation":"نحوه دیدن رابطه هدف‌ها بر همکاری اثر می‌گذارد. وقتی موفقیت خود را وابسته به شکست دیگری ببینیم، رفتار دفاعی محتمل‌تر می‌شود؛ هدف مشترک می‌تواند زمینه حل مسئله را تقویت کند.","source":"cooperation"}},{"id":6,"title":"واحد تخصصی؛ مانع یا شریک حل مسئله؟","concept":"همکاری بین‌واحدی و دیدن مسئله مشترک","evidence":"در یک درخواست متوقف، هر طرف هدف و نگرانی طرف دیگر را چگونه توضیح می‌دهد؟ از هر دو بپرسید چه کمکی از دیگری لازم دارند.","variants":{"managers":{"problem":"سایت برای بازگرداندن یک خودرو به کار، درخواست خرید فوری می‌دهد. مالی می‌گوید مدارک ناقص است و فنی می‌گوید مشخصات قطعه تأیید نشده. عملیات این پاسخ‌ها را مانع‌تراشی می‌نامد و برای دورزدن کنترل‌ها دنبال رابطه شخصی می‌رود.","analysis":["عملیات ممکن است واحد تخصصی را مانع ببیند و واحد تخصصی هم عملیات را بی‌دقت بداند؛ این برچسب‌ها گفت‌وگو را دفاعی می‌کنند.","اگر فقط موفقیت جداگانه واحد خود را ببینیم، اثر رفتارمان بر نتیجه مشترک پنهان می‌ماند.","ندیدن محدودیت طرف مقابل، پاسخ «نمی‌شود» و فشار «باید بشود» را به عادت تبدیل می‌کند."],"lesson":"پیش از دفاع از مرز واحد، مسئله و نگرانی طرف مقابل را بفهمید و مسئولیت خود در نتیجه مشترک را بپذیرید.","note":"همکاری با فهم متقابل شروع می‌شود، نه با حذف اختلاف تخصصی.","solution":["در گفت‌وگوی دو واحد، هر طرف ابتدا مسئله و نگرانی طرف دیگر را بازگو کند و از درستی آن بپرسد.","از دو مدیر بخواهید جمله «برای اینکه کار مشترک پیش برود، من چه رفتاری را تغییر می‌دهم؟» را کامل کنند.","به جای متهم‌کردن واحد دیگر، درباره رفتار مشخص و اثر آن بازخورد بدهید.","در جلسه بعد از یک همکاری مؤثر بین دو واحد قدردانی کنید؛ سهم هر دو طرف را ببینید."],"questions":["چه برچسبی به واحد مقابل زده‌ایم که مانع شنیدن حرفش شده است؟","رفتار خودمان چه سهمی در بسته‌شدن گفت‌وگو دارد؟"],"dialogue":"می‌فهمم حفظ معیار برای شما مهم است؛ نیاز عملیات را هم بشنویم و ببینیم هر طرف چه کمکی می‌تواند بکند."},"hq":{"problem":"درخواستی از سایت دریافت می‌کنید که مشخصات و تأیید لازم را ندارد. پاسخ می‌دهید: «طبق دستورالعمل امکان ندارد.» سایت دوباره تماس می‌گیرد و می‌گوید خودرو متوقف است؛ اما هنوز نمی‌داند دقیقاً چه چیزی باید بفرستد.","analysis":["ممکن است برای محافظت از خودمان فقط بند وظیفه را بگوییم و نیاز همکار را نبینیم.","پاسخ کلی و سرد، در طرف مقابل احساس طردشدن ایجاد می‌کند و تماس بعدی را پرتنش‌تر می‌کند.","کمک‌کردن با پذیرفتن مسئولیت خارج از اختیار فرق دارد؛ می‌توان هم مرز داشت و هم همراه بود."],"lesson":"پاسخ تخصصی وقتی مفیدتر است که طرف مقابل بعد از گفت‌وگو بداند چه کمکی می‌تواند دریافت کند.","note":"«وظیفه من نیست» را با راهنمایی روشن و محترمانه جایگزین کنید.","solution":["ابتدا بپرسید مسئله درخواست‌کننده چیست و تأخیر چه اثری بر او می‌گذارد.","محدودیت خود را بدون تحقیر توضیح دهید و کمک ممکن را پیشنهاد کنید.","اگر پاسخ در اختیار شما نیست، همکار را به فرد مناسب راهنمایی کنید و مطمئن شوید موضوع برای او روشن شده است.","یک بار از درخواست‌کننده بپرسید: «پاسخ من چقدر به جلو رفتن کار کمک کرد؟»"],"questions":["چگونه بدون عبور از حدود اختیار، همراه و کمک‌کننده باشیم؟","کدام جمله ما ممکن است برای طرف مقابل بی‌اعتنایی تلقی شود؟"],"dialogue":"این بخش در اختیار من نیست، اما می‌توانم کمک کنم مسئله روشن به مسئول مربوط برسد."},"operations":{"problem":"برای دریافت خدمت تعمیراتی مراجعه می‌کنید، اما گفته می‌شود مجوز یا شرح نقص کامل نیست. فکر می‌کنید تعمیرگاه نمی‌خواهد کمک کند و می‌خواهید مستقیم از یک آشنا بخواهید کار را انجام دهد.","analysis":["وقتی جواب دلخواه نمی‌شنویم، ممکن است تصور کنیم طرف مقابل نمی‌خواهد کمک کند.","صحبت تند، طرف مقابل را هم دفاعی می‌کند و پیدا کردن راه مشترک سخت‌تر می‌شود.","شرح روشن نیاز و گوش‌دادن به محدودیت او، شانس فهم متقابل را بیشتر می‌کند."],"lesson":"نیاز خود را روشن بگویید و قبل از قضاوت، دلیل پاسخ طرف مقابل را بشنوید.","note":"محکم حرف‌زدن با بی‌احترامی فرق دارد.","solution":["به جای «شما هیچ‌وقت کمک نمی‌کنید»، بگویید الان چه مشکلی دارید و چه کمکی می‌خواهید.","اگر پاسخ منفی است، دلیل را بپرسید و حرف طرف مقابل را قطع نکنید.","دوباره بگویید چه فهمیده‌اید و بپرسید قدم بعدی ممکن چیست.","اگر تنش بالا رفت، با کمک سرپرست گفت‌وگو را به مسئله مشخص برگردانید."],"questions":["آیا از جواب منفی، نیت بد نتیجه می‌گیریم؟","چگونه درخواست کمک را روشن و محترمانه مطرح کنیم؟"],"dialogue":"می‌خواهم دلیل این محدودیت را بفهمم؛ الان چه کمکی ممکن است؟"}},"theory":{"name":"نظریه همکاری و رقابت مورتون دویچ","explanation":"اگر موفقیت واحدها جدا از یکدیگر تعریف شود، دفاع از مرز واحد می‌تواند بر حل کار مشترک غلبه کند. دیدن وابستگی متقابل کمک می‌کند طرف مقابل را شریک نتیجه ببینیم.","source":"cooperation"}},{"id":7,"title":"تصمیم‌گیری بدون حضور ذی‌نفعان اصلی","concept":"شنیدن صدای افراد و مشارکت در تصمیم","evidence":"آیا افراد پیش از تصمیم فرصت بیان داشته‌اند؟ آیا بعداً فهمیده‌اند نظرشان چه اثری داشته یا چرا پذیرفته نشده است؟","variants":{"managers":{"problem":"در سناریو، ستاد زمان بارگیری را برای پاسخ به مشتری جلو می‌آورد؛ اما با سایت، تعمیرات و مسئول ایمنی درباره آمادگی هماهنگ نمی‌کند. راننده به مقصد می‌رسد و ظرفیت دریافت مهیا نیست. در مأموریت برون‌مرزی فرضی، همین خطا می‌تواند هماهنگی مدارک و نماینده مقصد را هم مختل کند.","analysis":["مدیر ممکن است سرعت تصمیم را با تصمیم‌گرفتن به‌تنهایی یکسان بداند.","دعوت از کارکنان پس از تصمیم قطعی می‌تواند مشارکت ظاهری بسازد و اعتماد را کم کند.","گاهی سکوت جلسه نشانه موافقت نیست؛ فرد فکر می‌کند نظرش اثری ندارد یا مخالفت هزینه دارد."],"lesson":"افراد را در جایی مشارکت دهید که اطلاعات یا اجرای کار به آنان وابسته است و درباره نتیجه مشارکت پاسخ بدهید.","note":"نظرخواستن بدون شنیدن و توضیح نتیجه، اعتماد نمی‌سازد.","solution":["پیش از تصمیم، از فرد نزدیک به کار بپرسید: «ما چه چیزی را از اینجا نمی‌بینیم؟»","در جمع، از دیدگاه متفاوت استقبال کنید؛ خودتان زودتر از همه پاسخ نهایی را اعلام نکنید.","پس از تصمیم توضیح دهید کدام نظر در انتخاب اثر گذاشته و کدام محدودیت مانع پذیرش پیشنهاد دیگر شده است.","از تیم بپرسید آیا می‌تواند بدون برچسب مخالفت، اطلاعات ناموافق را مطرح کند."],"questions":["آیا مشارکت خواسته‌ایم یا فقط تأیید تصمیم خودمان را؟","چه رفتاری به افراد نشان می‌دهد نظرشان واقعاً شنیده شده است؟"],"dialogue":"قبل از اینکه تصمیم را نهایی کنیم، می‌خواهم محدودیت‌هایی را بشنوم که شما در کار روزمره می‌بینید."},"hq":{"problem":"پیش از صدور برنامه حمل، زمان را در فایل تغییر می‌دهید و فقط برای مدیر خود می‌فرستید. سایت، مسئول اسناد و همکار شیفت بعدی هنوز نسخه قبلی را دارند. در مثال فرضی حمل برون‌مرزی، نماینده مقصد هم از تغییر بی‌خبر می‌ماند.","analysis":["ممکن است تصور کنیم چون تصمیم مدیر است، اطلاعات ما اهمیتی ندارد.","از طرف دیگر، اگر نظر ما پذیرفته نشود ممکن است احساس کنیم بی‌ارزش بوده‌ایم و از همکاری کنار بکشیم.","تفاوت دیدگاه ستاد و میدان می‌تواند منبع یادگیری باشد، اگر به رقابت بر سر برتری تبدیل نشود."],"lesson":"با اطلاعات روشن در تصمیم مشارکت کنید و پذیرفته‌نشدن پیشنهاد را با نادیده‌گرفته‌شدن خود یکی ندانید.","note":"دیدگاه متفاوت را بگویید و برای شنیدن دلیل تصمیم هم آماده باشید.","solution":["اثر تصمیم بر کار خود و همکاران را با یک مثال روشن توضیح دهید.","از همکار میدان بپرسید چه نکته‌ای از نگاه ستاد پنهان مانده است.","اگر پیشنهاد شما پذیرفته نشد، دلیل را بپرسید؛ بعد در اجرای تصمیم مجاز، مسئولانه همکاری کنید.","در بازخورد بعدی، نتیجه واقعی را بدون عبارت «گفته بودم» مطرح کنید."],"questions":["چه چیزی مانع بیان نظر کارشناسی ما می‌شود؟","چطور از تصمیمی که انتخاب اول ما نبوده، مسئولانه حمایت کنیم؟"],"dialogue":"یک نکته از اجرای کار می‌بینم که ممکن است به تصمیم کمک کند؛ اجازه بدهید کوتاه توضیح بدهم."},"operations":{"problem":"برنامه جدید به شما رسیده، اما شما می‌دانید در ساعت اعلام‌شده ورود به محل مورد نظر ممکن نیست. با خود می‌گویید: «ستاد حتماً می‌داند» و چیزی نمی‌گویید. بعد از رسیدن، منتظر می‌مانید و کار عقب می‌افتد.","analysis":["ممکن است فکر کنیم نظر کارکنان میدان برای ستاد مهم نیست.","ترس از مخالف دیده‌شدن می‌تواند اطلاعات مهم را پنهان نگه دارد.","اینکه نظر ما شنیده شود با اینکه همیشه پذیرفته شود فرق دارد."],"lesson":"تجربه خود را روشن بگویید؛ نظر شما می‌تواند چیزی را نشان دهد که دیگران ندیده‌اند.","note":"بیان محدودیت واقعی، بی‌احترامی نیست.","solution":["یک نکته مشخص از کار را با مثال به مسئول بگویید؛ موضوع را به شکایت کلی تبدیل نکنید.","پیشنهاد خود را کوتاه مطرح کنید و بگویید چه کمکی به کار می‌کند.","اگر پیشنهاد پذیرفته نشد، محترمانه دلیل را بپرسید و انتظار نهایی را روشن کنید.","به نظر همکار تازه‌وارد هم گوش بدهید؛ تجربه کمتر به معنای بی‌ارزش‌بودن نظر نیست."],"questions":["اگر بدانید نظر شما شنیده می‌شود، چه نکته‌ای را مطرح می‌کنید؟","سرپرست با چه رفتاری می‌تواند شما را به مشارکت تشویق کند؟"],"dialogue":"از نزدیک این وضعیت را دیده‌ام؛ می‌خواهم نکته‌ای بگویم که شاید به تصمیم کمک کند."}},"theory":{"name":"توانمندسازی روان‌شناختی؛ اسپریتزر","explanation":"این چارچوب به احساس معناداری کار، شایستگی، اختیار و اثرگذاری توجه می‌کند. شنیده‌شدن می‌تواند به احساس اثرگذاری کمک کند؛ مشارکت هم به معنای پذیرفته‌شدن همه پیشنهادها نیست.","source":"empowerment"}},{"id":8,"title":"سازمانی که همیشه در وضعیت فوری است","concept":"فشار کاری و تعارض انتظارها","evidence":"آیا فرد می‌تواند درباره ناتوانی در انجام هم‌زمان کارها حرف بزند؟ واکنش مدیر به اعلام محدودیت چیست؟ رفتار قهرمانانه پس از بحران بیشتر تشویق می‌شود یا پیشگیری؟","variants":{"managers":{"problem":"درخواست قطعه، پرداخت، برنامه حمل و جلسه ستاد همگی برچسب فوری دارند. کارکنان مرتب کار قبلی را رها می‌کنند. سفارش قابل پیش‌بینی دیر ثبت شده، اما تیم برای جبران آن تحت فشار تحویل قرار می‌گیرد و صدای هشدار میدان کمتر شنیده می‌شود.","analysis":["اگر مدیر فقط هنگام بحران توجه نشان دهد، افراد ممکن است کار آرام و پیشگیرانه را کم‌ارزش ببینند.","واژه «فوری» گاهی ابزار فشار برای گرفتن سهم بیشتر از وقت دیگران می‌شود.","کارکنان ممکن است برای ضعیف دیده‌نشدن، محدودیت خود را پنهان کنند و به همه قول بدهند."],"lesson":"کاهش فشار ناسالم از روشن‌کردن انتظارها و پذیرفتن محدودیت واقعی افراد شروع می‌شود.","note":"پیشگیری و اعلام زودهنگام مانع را هم ببینید، نه فقط قهرمان لحظه بحران را.","solution":["از کارکنان بپرسید: «کدام انتظارهای ما با هم جمع نمی‌شوند؟» و بدون سرزنش گوش دهید.","وقتی کار تازه‌ای می‌خواهید، روشن کنید چه انتظار قبلی تغییر می‌کند؛ تصمیم را به دوش فرد تنها نگذارید.","به خبر بد و اعلام محدودیت، با پرسش و حمایت پاسخ دهید؛ از عبارت «بقیه می‌توانند، تو چرا نه؟» فاصله بگیرید.","در مرور هفته، از کسی که زود هشدار داده یا از بحران پیشگیری کرده هم قدردانی کنید."],"questions":["آیا رفتار پاداش‌دهی ما به بحران‌سازی کمک می‌کند؟","کارکنان برای نه‌گفتن مسئولانه چه حمایتی از ما لازم دارند؟"],"dialogue":"می‌دانم هم‌زمان چند انتظار از شما داریم؛ بیایید روشن کنیم کدام را تغییر دهیم تا تعهد واقع‌بینانه شود."},"hq":{"problem":"سه واحد هم‌زمان می‌گویند کارشان فوری است. برای راضی‌کردن همه، به هر سه قول امروز می‌دهید. با چند بار قطع کار، یک اشتباه در مدارک رخ می‌دهد و هیچ درخواست کاملی تحویل نمی‌شود.","analysis":["برای مقبول‌بودن ممکن است همه درخواست‌ها را بپذیریم، حتی وقتی انجام هم‌زمان ممکن نیست.","مقایسه خود با همکاران و ترس از ضعیف دیده‌شدن، درخواست کمک را سخت می‌کند.","وقتی خسته و پراکنده می‌شویم، لحن ارتباطی ما هم ممکن است تند شود و تعارض تازه بسازد."],"lesson":"مرزبندی محترمانه و درخواست روشن‌کردن اولویت، رفتار مسئولانه است.","note":"محدودیت را زود بگویید؛ آن را تا لحظه شکست پنهان نکنید.","solution":["به جای «همه را انجام می‌دهم»، بگویید هم‌اکنون چه تعهدهایی پذیرفته‌اید.","از مسئول بخواهید بین انتظارهای ناسازگار تصمیم بگیرد و به توافق برسید.","اگر فشار روی لحن شما اثر گذاشت، مکث کنید و خواسته را روشن و بدون تندی بیان کنید.","برای درخواست کمک، یک نیاز مشخص بگویید؛ منتظر نمانید دیگران خودشان متوجه شوند."],"questions":["چه باوری باعث می‌شود کمک‌خواستن را ضعف بدانیم؟","چگونه محترمانه بگوییم انجام هم‌زمان این کارها ممکن نیست؟"],"dialogue":"می‌توانم این کار را بپذیرم، اگر درباره جابه‌جایی تعهد قبلی به توافق برسیم."},"operations":{"problem":"به شما می‌گویند بار باید زودتر برسد. مسیر و کارهای قبلی زمان برده و احساس خستگی می‌کنید. جمله «همه منتظرند» شما را تحت فشار قرار می‌دهد تا شرایط خودتان را پنهان کنید.","analysis":["جمله‌هایی مثل «مرد کار باش» ممکن است باعث شود خستگی و محدودیت خود را پنهان کنیم.","ترس از سرزنش یا ازدست‌دادن فرصت کار می‌تواند ما را به قول غیرواقعی وادار کند.","همکاران هم با تمسخر یا حمایت، بر بیان صادقانه مشکل اثر می‌گذارند."],"lesson":"مسئولیت‌پذیری یعنی وضعیت واقعی را بگویید، نه اینکه برای حفظ ظاهر قول بدهید.","note":"کمک‌خواستن به‌موقع، بخشی از حرفه‌ای‌بودن است.","solution":["در زمان ایمن، وضعیت خود را روشن بگویید و از عبارت‌های مبهم مثل «یک‌جوری می‌رسم» فاصله بگیرید.","از مسئول بخواهید انتظار قابل انجام را روشن کند؛ فشار را با رفتار پرخطر جبران نکنید.","اگر همکار درباره خستگی یا فشار حرف زد، او را مسخره نکنید و تشویقش کنید موضوع را مسئولانه مطرح کند.","پایان شیفت بگویید کدام فشار را زود گفتید و چه کمکی دریافت کردید."],"questions":["چه حرف‌هایی در جمع باعث پنهان‌کردن خستگی می‌شود؟","چطور به همکارمان کمک کنیم بدون خجالت محدودیتش را بگوید؟"],"dialogue":"می‌خواهم مسئولانه کار کنم؛ با این وضعیت نمی‌توانم همان قول قبلی را بدهم و به تعیین تکلیف نیاز دارم."}},"theory":{"name":"تعارض نقش و هدف‌گذاری","explanation":"چند انتظار ناسازگار می‌تواند فرد را تحت فشار بگذارد. هدف روشن زمانی کمک‌کننده است که توان، تعهد و بازخورد هم دیده شود؛ صرف درخواست نتیجه بیشتر، مسئله ظرفیت و تعارض هدف را حل نمی‌کند.","source":"role","secondary":"goals"}},{"id":9,"title":"ایمنی؛ آموزش کافی است یا نظارت هم لازم است؟","concept":"هنجار گروه و رفتار ایمن","evidence":"وقتی کسی برای رعایت ایمنی مکث یا سؤال می‌کند، مدیر و همکاران چه واکنشی نشان می‌دهند؟ چه رفتارهایی در جمع تحسین یا تمسخر می‌شوند؟","variants":{"managers":{"problem":"در مثال آموزشی حمل مواد اسیدی، کارکنان آموزش دیده‌اند؛ اما هنگام فشار تحویل، بعضی کنترل‌های پیش از کار با عجله انجام می‌شود. مدیر فقط تعداد نفرات آموزش‌دیده را می‌پرسد و سرپرست از متوقف‌شدن کار نگران است.","analysis":["اگر کار سریع تشویق شود ولی طرح نگرانی با بی‌حوصلگی روبه‌رو شود، پیام عملی با پیام کلاس متفاوت است.","هنجار گروه ممکن است این باشد که «آدم باتجربه سؤال نمی‌پرسد»؛ چنین باوری باید از گفت‌وگو با افراد بررسی شود.","رفتار نامناسب را فقط به بی‌توجهی فرد نسبت ندهید؛ فشار جمع، واکنش سرپرست و امکانات واقعی هم اثر دارند."],"lesson":"فرهنگ ایمنی در واکنش روزمره به سؤال، نگرانی و رفتار مسئولانه شکل می‌گیرد.","note":"در این کیس، موضوع ما واکنش انسانی و هنجار گروه است؛ تصمیم فنی با مسئول صلاحیت‌دار می‌ماند.","solution":["از کارکنان بخواهید بگویند کدام واکنش مدیر یا همکار، گفتن نگرانی را سخت می‌کند.","وقتی کسی نگرانی را مطرح می‌کند، ابتدا تشکر کنید و مسئله را بشنوید؛ بدون بررسی برچسب ترسو یا دردسرساز نزنید.","اگر خودتان با عجله پیام نامناسبی داده‌اید، آن را اصلاح کنید و مسئولیت اثرش را بپذیرید.","یک نمونه رفتار مسئولانه را مشخص قدردانی کنید و درباره موانع تکرار آن گفت‌وگو کنید؛ الزامات فنی تابع رویه مصوب محل است."],"questions":["تیم از رفتار ما یاد می‌گیرد ایمنی واقعاً چقدر مهم است؟","چه چیزی در جمع، سکوت درباره نگرانی را پاداش می‌دهد؟"],"dialogue":"ممنون که گفتی؛ می‌خواهم نگرانی‌ات را بفهمم و بدانم چه فشاری باعث شده طرح آن سخت باشد."},"hq":{"problem":"برای رعایت موعد مشتری، برنامه حمل را فشرده می‌کنید. از سایت خبر می‌رسد که کنترل ایمنی و آمادگی خودرو هنوز تکمیل نشده است. می‌خواهید فقط پیام «لطفاً سریع‌تر» بفرستید تا کار عقب نماند.","analysis":["گاهی فاصله ستاد از میدان باعث می‌شود پیام «فقط زودتر انجامش بده» بی‌اهمیت به نظر برسد.","اگر نگرانی میدان را به بهانه‌جویی تعبیر کنیم، کارکنان دفعه بعد کمتر واقعیت را می‌گویند.","ما با لحن و نوع پیگیری خود بر هنجارهای رفتاری میدان اثر می‌گذاریم، حتی وقتی در محل حضور نداریم."],"lesson":"حمایت از رفتار مسئولانه، از کیفیت پاسخ ما به نگرانی دیگران شروع می‌شود.","note":"نگرانی را پیش از قضاوت بشنوید؛ سرعت را تنها معیار ارزش‌گذاری نکنید.","solution":["وقتی از میدان نگرانی می‌شنوید، ابتدا بپرسید چه اتفاقی افتاده و چه کمکی لازم است.","در پیام خود روشن کنید که بیان صادقانه وضعیت ارزشمند است؛ از فشار و مقایسه تحقیرآمیز پرهیز کنید.","محدودیت واقعی را به مسئول مربوط منتقل کنید، بدون اینکه خودتان تأیید فنی صادر کنید.","بعداً از فرد بپرسید پاسخ شما کمک‌کننده بوده یا فشار بیشتری ایجاد کرده است."],"questions":["کدام جمله معمول ما ممکن است نگرانی میدان را خاموش کند؟","چطور نشان دهیم بیان مسئولانه مسئله را ارزشمند می‌دانیم؟"],"dialogue":"قبل از صحبت درباره موعد، می‌خواهم نگرانی شما را درست بفهمم؛ لطفاً وضعیت واقعی را بگویید."},"operations":{"problem":"در یک موقعیت آموزشی، پیش از شروع کار با خودرو یا محل بارگیری مورد مشکوکی می‌بینید. همکار می‌گوید: «دیروز هم همین بود؛ شروع کنیم.» شما آموزش دیده‌اید، اما نمی‌خواهید باعث تأخیر گروه شوید.","analysis":["ممکن است برای پذیرفته‌شدن در جمع، از رفتار همکاران قدیمی پیروی کنیم.","وقتی نگرانی با شوخی و تمسخر پاسخ داده می‌شود، گفتن آن سخت‌تر می‌شود.","تجربه زیاد به معنای بی‌نیازی از سؤال نیست؛ آدم حرفه‌ای هم می‌تواند ابهام داشته باشد."],"lesson":"همراهی با گروه نباید شما را از گفتن نگرانی واقعی بازدارد.","note":"همکار نگران را مسخره نکنید؛ حرف او می‌تواند به همه کمک کند.","solution":["نگرانی خود را کوتاه و دقیق مطرح کنید؛ برای باتجربه دیده‌شدن آن را پنهان نکنید.","اگر کسی گفت «همه همین کار را می‌کنند»، از مسئول مجاز روشن‌شدن انتظار را بخواهید.","به همکار تازه‌وارد بگویید سؤال‌پرسیدن و کمک‌خواستن در گروه پذیرفته است.","رفتارهای ایمنی را طبق آموزش مصوب دنبال کنید؛ در گفت‌وگوی گروهی بر احترام و حمایت از گزارش مسئولانه تمرکز کنید."],"questions":["آیا برای پذیرفته‌شدن در جمع، نگرانی خود را پنهان کرده‌ایم؟","چطور به همکار نگران نشان دهیم حرفش مهم است؟"],"dialogue":"ممکن است تجربه من کمتر باشد، اما این موضوع نگرانم کرده و می‌خواهم آن را روشن کنم."}},"theory":{"name":"نظریه شناختی اجتماعی وود و بندورا","explanation":"رفتار فرد، برداشت او از توانایی و پیام‌های محیط بر یکدیگر اثر می‌گذارند. افراد از مشاهده رفتار دیگران و پیامدهای آن هم یاد می‌گیرند؛ پس آموزش گفتاری باید با الگوی رفتاری هماهنگ باشد.","source":"learning"}},{"id":10,"title":"از کنترل شخصی تا نظم، نظارت و پاسخگویی","concept":"اعتماد، توانمندسازی و خودباوری","evidence":"هنگام اشتباه، مدیر کمک می‌کند فرد یاد بگیرد یا فوراً کار را از او پس می‌گیرد؟ کارکنان کجا از ترس واکنش مدیر منتظر می‌مانند؟","variants":{"managers":{"problem":"مدیر برای اطمینان از کار سایت‌ها، درباره هر درخواست و هر جابه‌جایی تماس می‌گیرد. وقتی در جلسه است، تأییدهای کوچک هم می‌ماند. کارکنان یاد گرفته‌اند برای هر تصمیم منتظر او باشند و مشکلات مهم میان جزئیات گم می‌شود.","analysis":["مدیر ممکن است باور داشته باشد فقط با دخالت دائمی می‌تواند از نتیجه مطمئن شود.","کارکنان با پس‌گرفتن مکرر کار یاد می‌گیرند که ابتکارشان ارزش یا امنیت ندارد.","نبود آمادگی واقعی فرد هم باید دیده شود؛ اعتماد بدون آموزش و حمایت، رهاکردن اوست."],"lesson":"به افراد فرصت تصمیم متناسب بدهید، از یادگیری آنان حمایت کنید و درباره نتیجه بازخورد روشن بدهید.","note":"به جای انجام‌دادن کار به جای فرد، توان انجام آن را در او تقویت کنید.","solution":["درباره یک کار مشخص بپرسید: «برای انجام مستقل‌تر چه چیز را بلدی و کجا حمایت لازم داری؟»","انتظار و مرز اختیار را روشن کنید و درباره زمان گفت‌وگوی بعدی توافق کنید.","وقتی فرد سؤال می‌کند، پیش از دادن جواب بپرسید خودش چه گزینه‌ای می‌بیند و چرا.","بعد از اجرا، یک نقطه قوت و یک زمینه بهبود را با مثال بگویید؛ به‌خاطر یک خطا همه اختیار را خودکار پس نگیرید."],"questions":["کنترل ما از نیاز واقعی کار می‌آید یا اضطراب خودمان؟","چگونه حمایت کنیم که فرد مستقل‌تر شود؟"],"dialogue":"می‌خواهم خودت این کار را جلو ببری؛ بگو چه حمایتی لازم داری و کجا با هم نتیجه را مرور کنیم."},"hq":{"problem":"برای یک درخواست، در چند فایل و پیام مختلف وضعیت می‌نویسید و هر بار تلفنی هم گزارش می‌دهید. وقتی مدیر نیست، نمی‌دانید کدام بخش کار را می‌توانید جلو ببرید. وقت گزارش‌دادن بیشتر شده، اما مانع حل نشده است.","analysis":["اگر برای هر اقدام تأیید بخواهیم، ممکن است ناخواسته وابستگی به مدیر را بیشتر کنیم.","گاهی تجربه برخورد تند باعث شده از پیشنهاد خودمان صرف‌نظر کنیم.","استقلال مسئولانه با پنهان‌کردن اشتباه یا تصمیم خارج از اختیار فرق دارد."],"lesson":"در محدوده اختیار ابتکار نشان دهید و برای بخش دشوار، کمک مشخص بخواهید.","note":"هنگام سؤال فقط مسئله نبرید؛ برداشت و پیشنهاد خود را هم مطرح کنید.","solution":["پیش از مراجعه به مدیر، بگویید مسئله را چگونه فهمیده‌اید و چه گزینه‌هایی دارید.","روشن کنید در کدام بخش اختیار دارید و برای کدام بخش حمایت یا تصمیم لازم است.","بعد از اقدام، نتیجه و آنچه یاد گرفته‌اید را صادقانه مطرح کنید.","از مدیر درباره یک رفتار مشخص بازخورد بخواهید تا دفعه بعد مستقل‌تر عمل کنید."],"questions":["چه چیزی باعث می‌شود داخل اختیار خود هم منتظر بمانیم؟","برای مستقل‌ترشدن، کدام مهارت یا حمایت را لازم داریم؟"],"dialogue":"برداشت من این است و این گزینه را پیشنهاد می‌کنم؛ برای این بخش از شما راهنمایی می‌خواهم."},"operations":{"problem":"سرپرست مدام تماس می‌گیرد تا بداند کار کجاست. گاهی وسط کار یا رانندگی نمی‌توانید پاسخ دهید. از طرفی تغییر وضعیت را هم طبق زمان مشخصی خبر نمی‌دهید و او مجبور می‌شود دوباره پیگیری کند.","analysis":["اگر همیشه کار از ما پس گرفته شود، ممکن است فکر کنیم توان انجامش را نداریم.","اگر بدون آموزش از ما انتظار استقلال داشته باشند، اضطراب و اشتباه بیشتر می‌شود.","برای خوب دیده‌شدن ممکن است چیزی را که بلد نیستیم پنهان کنیم؛ این به یادگیری کمک نمی‌کند."],"lesson":"آنچه می‌دانید را مسئولانه انجام دهید و درباره چیزی که نمی‌دانید کمک بخواهید.","note":"کمک‌خواستن به‌موقع، فرصت یادگیری می‌سازد.","solution":["به سرپرست بگویید کدام بخش کار را بلد هستید و کدام بخش هنوز برایتان روشن نیست.","پس از توضیح، برداشت خود را بازگو کنید تا معلوم شود درست فهمیده‌اید.","در محدوده آموزش و اختیار خود اقدام کنید؛ برای نشان‌دادن توانایی، از مرز صلاحیت عبور نکنید.","بعد از کار، یک نکته را که یاد گرفته‌اید بگویید و برای بهترشدن بازخورد بخواهید."],"questions":["چه واکنشی از سرپرست به شما اعتمادبه‌نفس بیشتری می‌دهد؟","چگونه بگوییم بخشی از کار را هنوز بلد نیستیم؟"],"dialogue":"این بخش را می‌توانم انجام بدهم؛ برای این قسمت هنوز به توضیح و تمرین نیاز دارم."}},"theory":{"name":"توانمندسازی روان‌شناختی؛ اسپریتزر","explanation":"توانمندی فقط واگذاری کار نیست. فرد باید کار را معنادار بداند، احساس شایستگی کند، اختیار متناسب داشته باشد و اثر کارش را ببیند. کنترل دائمی می‌تواند این تجربه را تضعیف کند.","source":"empowerment"}},{"id":11,"title":"رفتار مدیر؛ پیام فرهنگی سازمان","concept":"الگوی رفتاری مدیر و پیام فرهنگی","evidence":"آخرین بار که کسی خبر بد داد، مدیر چه گفت و چه کرد؟ آیا برای رفتار خودش همان معیاری را رعایت کرد که از دیگران می‌خواهد؟","variants":{"managers":{"problem":"مدیر در جلسه بر احترام، دقت و ایمنی تأکید می‌کند؛ اما وقتی تأخیر پیش می‌آید، در جمع با سرپرست تند صحبت می‌کند و می‌گوید «فعلاً کار را راه بیندازید». کارکنان می‌بینند سرعت تحویل تشویق می‌شود، ولی گزارش مسئله با واکنش تند روبه‌روست.","analysis":["ممکن است مدیر باور داشته باشد تندی‌کردن در فشار، برای گرفتن نتیجه لازم است؛ تیم از همین رفتار یاد می‌گیرد.","اگر مدیر خطای خود را نپذیرد ولی از کارکنان پاسخ‌گویی بخواهد، معیار دوگانه ساخته می‌شود.","یک رفتار، کل فرهنگ را تعریف نمی‌کند؛ اما تکرار رفتار و واکنش دیگران به آن، سرنخ مهمی است."],"lesson":"پیام فرهنگی مدیر در لحظه‌های دشوار روشن‌تر از سخنرانی او دیده می‌شود.","note":"از خودتان همان رفتاری را بخواهید که از تیم انتظار دارید.","solution":["آخرین موقعیت فشار را مرور کنید: چه گفتید، چه اثری گذاشت و چه پیام ناخواسته‌ای داشت؟","اگر تند یا ناعادلانه رفتار کرده‌اید، اثرش را بپذیرید و بدون توجیه آن را اصلاح کنید.","در دریافت خبر بد ابتدا گوش دهید و پرسش روشن بپرسید؛ قضاوت عجولانه را عقب بیندازید.","از همکاران درباره یک رفتار مشخص بازخورد بخواهید و بعداً بگویید بر اساس آن چه تغییری داده‌اید."],"questions":["اگر تیم فقط رفتار ما را ببیند، چه ارزش‌هایی را واقعی می‌داند؟","کدام عذرخواهی یا اصلاح رفتار، اعتبار ما را بیشتر می‌کند؟"],"dialogue":"لحن من در آن گفت‌وگو مناسب نبود؛ مسئولیتش را می‌پذیرم و می‌خواهم مسئله را این بار با احترام بررسی کنیم."},"hq":{"problem":"مدیر از همه دقت می‌خواهد، اما یک بار می‌گوید اطلاعات تأییدنشده را برای سرعت بیشتر قطعی اعلام کنید. شما نگرانید مخالفت بی‌احترامی تلقی شود و همان عبارت قطعی را در پاسخ به سایت می‌نویسید.","analysis":["فشار مقام بالاتر می‌تواند ما را به رفتار خلاف دقت یا احترام حرفه‌ای وادار کند.","دیدن رفتار نامناسب مدیر ممکن است باعث شود همان رفتار را با دیگران تکرار کنیم.","ما هم در تجربه همکاران نقش داریم؛ اثر رفتار خود را نمی‌توانیم کاملاً به مدیر نسبت دهیم."],"lesson":"با حفظ احترام، بر رفتار حرفه‌ای خود پایبند بمانید و ابهام یا نگرانی را روشن مطرح کنید.","note":"رفتار نامناسب بالادست، مجوز رفتار نامناسب ما نیست.","solution":["وقتی خواسته‌ای مبهم یا مسئله‌ساز است، پیش از اجرا درباره انتظار و پیامدش سؤال کنید.","اگر برخورد تندی دیده‌اید، همان لحن را به همکار یا درخواست‌کننده بعدی منتقل نکنید.","برای بازخورد به مدیر، زمان مناسب انتخاب و رفتار مشخص و اثر آن را بدون قضاوت شخصیتی توضیح دهید؛ در موضوع حساس از مسیر مستقل کمک بگیرید.","اگر خودتان اشتباه کردید، آن را روشن بپذیرید و اقدام اصلاحی بگویید."],"questions":["کدام رفتار بالادست را ناخواسته با دیگران تکرار می‌کنیم؟","چگونه نگرانی خود را محترمانه و روشن بیان کنیم؟"],"dialogue":"وقتی در جمع با آن لحن پاسخ گرفتم، بیان ادامه مسئله برایم سخت شد؛ می‌خواهم درباره شیوه گفت‌وگو توافق کنیم."},"operations":{"problem":"سرپرست در شروع شیفت می‌گوید همه باید قاعده سایت را رعایت کنند، اما وقتی عجله دارد خودش از آن عبور می‌کند. همکار تازه‌وارد می‌پرسد: «پس کدام را انجام بدهیم؛ حرفش یا کارش را؟»","analysis":["ما از رفتار سرپرست و همکار باتجربه یاد می‌گیریم، حتی وقتی توضیحی نمی‌دهند.","اگر رفتار نامناسب بی‌پاسخ بماند، ممکن است تصور کنیم در این گروه عادی و پذیرفته است.","خود ما هم با برخورد با نفر بعدی، همین عادت را ادامه می‌دهیم یا تغییر می‌دهیم."],"lesson":"هر نفر با رفتار روزمره خود به دیگران نشان می‌دهد چه چیزی در گروه پذیرفته است.","note":"اگر اشتباه کردید، پذیرفتن و اصلاح‌کردن آن رفتار حرفه‌ای است.","solution":["با همکار جدید همان‌طور رفتار کنید که دوست دارید با خودتان رفتار شود.","اگر فردی قاعده یا احترام را رعایت نکرد، از او تقلید نکنید و انتظار درست را از مسئول روشن بخواهید.","در اختلاف، درباره رفتار حرف بزنید؛ به شخصیت فرد توهین نکنید.","اگر خودتان تند حرف زده‌اید، اثرش را بپذیرید و گفت‌وگو را محترمانه ادامه دهید."],"questions":["همکار تازه‌وارد از رفتار ما چه چیزی یاد می‌گیرد؟","چطور می‌توانیم یک عادت نامناسب گروه را ادامه ندهیم؟"],"dialogue":"حرفم را تند گفتم؛ منظورم این است که درباره این کار به توافق روشن نیاز داریم."}},"theory":{"name":"فرهنگ سازمانی شاین و یادگیری از الگوها","explanation":"ارزش‌های اعلام‌شده باید در کنار رفتارهای روزمره بررسی شوند. کارکنان از آنچه مدیر عملاً انجام می‌دهد و جدی می‌گیرد هم یاد می‌گیرند؛ فاصله حرف و عمل، پرسشی برای شناخت فرهنگ است.","source":"schein","secondary":"learning"}},{"id":12,"title":"استخدام در سایت‌ها؛ چه کسی تصمیم می‌گیرد؟","concept":"عدالت در جذب و پذیرش همکار جدید","evidence":"آیا همه افراد فرصت مشابه برای نشان‌دادن توانایی دارند؟ رابطه شخصی چقدر بر قضاوت اثر دارد؟ همکار جدید در شروع کار با چه برخوردی روبه‌رو می‌شود؟","variants":{"managers":{"problem":"سایت برای پوشش کمبود نیرو، به یک فرد آشنا قول شروع کار می‌دهد. منابع انسانی بعداً متوجه می‌شود ارزیابی شغلی و تأیید ظرفیت انجام نشده است. عملیات می‌گوید کار معطل می‌ماند و ستاد می‌گوید مسئول پیامد استخدام نیست.","analysis":["در فشار کمبود نیرو، آشنایی ممکن است جای گفت‌وگوی دقیق درباره توانایی و انتظار شغل را بگیرد.","ستاد و محل اجرا ممکن است برای حفظ اختیار خود رقابت کنند و مسئولیت تصمیم را به دیگری بدهند.","رفتار ما با فرد معرفی‌شده و افراد دیگر، به کارکنان پیام می‌دهد که رابطه مهم‌تر است یا شایستگی و انصاف."],"lesson":"جذب منصفانه و ورود محترمانه همکار جدید، از نخستین پیام‌های فرهنگ سازمان است.","note":"معرفی‌شدن می‌تواند راه آشنایی باشد؛ دلیل کافی برای برتری فرد نیست.","solution":["از خود بپرسید اگر همین فرد معرفی‌کننده قدرتمندی نداشت، همان فرصت و قضاوت را دریافت می‌کرد؟","با مدیر محل اجرا و منابع انسانی درباره انتظار رفتاری از شغل توافق کنید؛ اختلاف اختیار را پشت نام داوطلب پنهان نکنید.","در گفت‌وگو با افراد، فرصت مشابه برای ارائه تجربه بدهید و از وعده شخصی خارج از اختیار پرهیز کنید.","در شروع همکاری، فرد را محترمانه معرفی کنید و مسئول راهنمایی او را روشن کنید؛ پس از چند روز تجربه ورودش را بشنوید."],"questions":["آیا رابطه شخصی روی برداشت ما از شایستگی اثر گذاشته است؟","همکار جدید از روزهای اول، چه چیزی درباره فرهنگ ما یاد می‌گیرد؟"],"dialogue":"معرفی شما محترم است؛ می‌خواهیم فرصت ارزیابی منصفانه و انتظار روشن برای همه وجود داشته باشد."},"hq":{"problem":"فردی برای کار در سایت تماس می‌گیرد و می‌گوید با مسئول سایت توافق کرده است. پرونده او هنوز کامل نیست و شما نمی‌دانید باید معرفی‌نامه شروع کار صادر کنید یا منتظر تأیید بمانید. سایت هم برای سرعت فشار می‌آورد.","analysis":["رودربایستی با معرف ممکن است ما را به وعده زودهنگام یا رفتار متفاوت با افراد وادار کند.","ابهام درباره نقش ستاد و محل اجرا، داوطلب را بین پاسخ‌های متناقض نگه می‌دارد.","برخورد سرد یا بی‌پاسخ‌گذاشتن فرد، پیش از ورود هم تجربه نامناسبی از سازمان می‌سازد."],"lesson":"حتی وقتی تصمیم جذب در اختیار شما نیست، کیفیت برخورد و صداقت پاسخ در اختیار شماست.","note":"به همه احترام بگذارید؛ درباره نتیجه‌ای که نمی‌دانید قول ندهید.","solution":["در پاسخ به فرد معرفی‌شده، وضعیت واقعی و انتظار قابل اتکا را بدون امتیاز ویژه توضیح دهید.","اگر از دو مسئول پاسخ متفاوت می‌شنوید، برای روشن‌شدن انتظار کمک بخواهید؛ تناقض را به دوش داوطلب نگذارید.","با اطلاعات شخصی افراد محرمانه و محترمانه برخورد کنید و در جمع درباره آنان قضاوت نکنید.","به همکار تازه‌وارد کمک کنید افراد و انتظارهای کاری را بشناسد؛ از او بپرسید چه چیزی هنوز مبهم است."],"questions":["چطور فشار معرف را بدون بی‌احترامی مدیریت می‌کنیم؟","کدام رفتار کوچک ما، تجربه ورود فرد را بهتر می‌کند؟"],"dialogue":"هنوز تصمیم نهایی اعلام نشده؛ می‌خواهم وضعیت را شفاف بگویم تا انتظار نادرست ایجاد نشود."},"operations":{"problem":"همکار تازه‌ای به شیفت معرفی شده است. یکی می‌گوید «راننده باتجربه‌ای است، زود کار را به او بدهیم»، اما معلوم نیست آشنایی با سایت، تجهیزات و مجوزهای لازم بررسی شده باشد. شما قرار است کار را به او تحویل دهید.","analysis":["ممکن است همکار تازه‌وارد را به دلیل معرف یا تجربه قبلی، زود قضاوت کنیم.","شوخی تحقیرآمیز و امتحان‌کردن بی‌دلیل فرد جدید، پرسیدن و یادگرفتن را سخت می‌کند.","وقتی انتظار کار روشن نباشد، فرد ممکن است برای پذیرفته‌شدن ادعای دانستن کند."],"lesson":"به همکار تازه‌وارد فرصت یادگیری و احترام بدهید؛ درباره او با شواهد رفتار قضاوت کنید.","note":"تازه‌واردبودن ضعف نیست و معرفی‌شدن هم برتری خودکار نیست.","solution":["خودتان را معرفی کنید و از فرد بپرسید چه چیزی برایش تازه یا مبهم است.","با حوصله انتظارهای روزمره و راه کمک‌خواستن را توضیح دهید؛ او را برای پرسیدن مسخره نکنید.","به جای برچسب «آدم فلانی»، رفتار واقعی همکار را ببینید.","اگر کار یا نقشی برای او روشن نیست، به سرپرست بگویید تا انتظار مشخص شود؛ او را در ابهام تنها نگذارید."],"questions":["روز اول خودمان چه نوع برخوردی را لازم داشتیم؟","چه شوخی یا برچسبی یادگیری همکار جدید را سخت می‌کند؟"],"dialogue":"اگر چیزی روشن نیست راحت بپرس؛ هیچ‌کس از روز اول همه چیز را نمی‌داند."}},"theory":{"name":"عدالت سازمانی و وضوح نقش","explanation":"عدالت رویه‌ای به منصفانه‌بودن روش تصمیم توجه دارد. در تصمیم مشترک جذب، انتظار مبهم از ستاد و محل اجرا می‌تواند اختلاف نقش بسازد؛ معرفی فرد و تصمیم‌گیری منصفانه درباره او باید از هم تفکیک شوند.","source":"justice","secondary":"role"}},{"id":13,"title":"امنیت روانی و فیزیکی کارکنان","concept":"امنیت روانی و امکان بیان نگرانی","evidence":"وقتی کسی سؤال یا اشتباه را مطرح می‌کند، واکنش نخست دیگران چیست؟ آیا فرد بعداً از گفتن پشیمان شده است؟ جزئیات حساس را در جمع مطرح نکنید.","variants":{"managers":{"problem":"در جلسه گفته می‌شود مشکل مهمی وجود ندارد. در گفت‌وگوی خصوصی، کارکنان از ترس تحقیر یا از دست‌دادن مأموریت، درباره خستگی، نقص و برخورد نامناسب حرف می‌زنند. مدیر، سکوت جمع را نشانه رضایت و نبود خطر برداشت کرده است.","analysis":["کارکنان ممکن است برای حفظ تصویر توانمند خود، سؤال یا خطا را پنهان کنند.","تندی، تمسخر یا بی‌اثرماندن گزارش به آنان یاد می‌دهد سکوت کم‌هزینه‌تر است.","سکوت جلسه را رضایت یا نبود مسئله ندانید؛ ترس از واکنش باید بررسی شود."],"lesson":"مدیر با واکنش خود تعیین می‌کند خبر بد دفعه بعد زودتر گفته شود یا پنهان بماند.","note":"حفظ حرمت فرد و بررسی منصفانه مسئولیت باید هم‌زمان وجود داشته باشند.","solution":["خودتان یک مورد ندانستن یا خطای قابل طرح را بپذیرید تا سؤال‌پرسیدن را عادی کنید.","وقتی نگرانی می‌شنوید، ابتدا تشکر و پرسش روشن داشته باشید؛ از تحقیر و تهدید پرهیز کنید.","روشن بگویید چه چیزی را می‌توانید محرمانه نگه دارید و چه چیزی برای رسیدگی باید به مرجع مجاز برسد؛ قول محرمانگی مطلق ندهید.","نتیجه پیگیری را در حد مجاز به فرد برگردانید و از تلافی‌جویی جلوگیری کنید؛ در خطر فوری، مسیر مصوب اضطراری مقدم است."],"questions":["آیا افراد برای حفظ تصویر خود از ما چیزی را پنهان می‌کنند؟","واکنش نخست ما به اشتباه، چه چیزی به تیم یاد می‌دهد؟"],"dialogue":"ممنون که مطرح کردی؛ می‌خواهیم واقعیت را بفهمیم و منصفانه رسیدگی کنیم، نه اینکه کسی را تحقیر کنیم."},"hq":{"problem":"همکار می‌گوید از برخورد توهین‌آمیز یا فشار برای پنهان‌کردن یک مشکل ناراحت است. برای همدلی می‌خواهید پیام او را در گروه بفرستید تا همه مطلع شوند. اما او از پیامدهای بعدی نگران است.","analysis":["گاهی همکار برای شنیده‌شدن حرف می‌زند، اما ما فوراً نصیحت یا قضاوت می‌کنیم.","بازنشر داستان او بدون رضایت و ضرورت، اعتماد را می‌شکند.","حمایت واقعی یعنی هم شنیدن نگرانی و هم حفظ اختیار فرد در قدم‌های ممکن؛ موضوع حساس نیازمند مسیر مناسب است."],"lesson":"پیش از راهنمایی، نگرانی و نیاز فرد را بفهمید؛ حمایت را با انتشار حرف او اشتباه نگیرید.","note":"برای همدلی لازم نیست قول نتیجه قطعی بدهید.","solution":["گوش دهید و بپرسید: «الان چه چیزی بیشتر نگرانت کرده و چه کمکی می‌خواهی؟»","از کوچک‌شمردن احساس فرد با جمله‌هایی مثل «حساس نباش» پرهیز کنید.","حدود نقش خود و مسیر مستقل رسیدگی را توضیح دهید؛ اطلاعات حساس را در گروه منتشر نکنید.","اگر خطری فوری است، طبق مسیر مصوب کمک بگیرید؛ در موضوع غیرفوری، درباره قدم بعدی با خود فرد روشن صحبت کنید."],"questions":["آیا واقعاً گوش می‌دهیم یا زود به نصیحت می‌رویم؟","چگونه از فرد حمایت کنیم بدون اینکه اختیارش را بگیریم؟"],"dialogue":"می‌شنوم که این برخورد نگرانت کرده؛ قبل از هر پیشنهادی، می‌خواهم بفهمم چه حمایتی برایت مفید است."},"operations":{"problem":"خسته‌اید یا وضعیتی نگران‌کننده دیده‌اید، اما فکر می‌کنید اگر بگویید، شما را ضعیف می‌دانند یا مأموریت بعدی را نمی‌دهند. همکار دیگری هم از برخورد نامناسب ناراحت است و جرئت طرح آن را ندارد.","analysis":["ترس از ترسو یا ناتوان دیده‌شدن می‌تواند سؤال و نگرانی را خاموش کند.","تمسخر همکاران هم به اندازه واکنش سرپرست مهم است.","پنهان‌کردن مسئله شاید در لحظه راحت‌تر باشد، اما یادگیری و رسیدگی را دشوار می‌کند."],"lesson":"با احترام حرف بزنید و به دیگران هم فرصت بدهید نگرانی خود را بگویند.","note":"سؤال‌پرسیدن و بیان اشتباه، با بی‌مسئولیتی فرق دارد.","solution":["نگرانی خود را با یک مثال روشن بیان کنید؛ به جای قضاوت درباره افراد، اتفاق را توضیح دهید.","اگر همکار سؤال کرد، با شوخی تحقیرآمیز جواب ندهید و کمکش کنید موضوع را روشن کند.","اگر اشتباه کرده‌اید، آن را پنهان نکنید؛ بگویید چه شده و برای قدم بعدی کمک بخواهید.","اگر از مسئول مستقیم نگران هستید، از مسیر مستقل معرفی‌شده کمک بگیرید؛ برای خطر فوری مسیر اضطراری محل را دنبال کنید."],"questions":["چه واکنشی باعث می‌شود دیگر نگرانی خود را نگویید؟","گروه ما چگونه می‌تواند پرسیدن را آسان‌تر کند؟"],"dialogue":"گفتن این موضوع برایم راحت نیست، اما می‌خواهم آن را زود مطرح کنم تا مسئولانه پیگیری شود."}},"theory":{"name":"امنیت روانی تیم؛ ایمی ادموندسون","explanation":"امنیت روانی، باور مشترک به امکان پرسیدن، کمک‌خواستن و مطرح‌کردن اشتباه یا نگرانی بدون تحقیر بین‌فردی است. این مفهوم با راحت‌طلبی، دوستی صمیمی یا حذف پاسخ‌گویی یکسان نیست.","source":"safety"}},{"id":14,"title":"اختیار، مسئولیت و پاسخگویی مدیران","concept":"وضوح انتظار و اختیار متناسب","evidence":"آیا مدیر و همکارش برداشت یکسانی از مسئولیت و اختیار دارند؟ فرد کجا احساس می‌کند هر انتخابی می‌تواند به سرزنش منجر شود؟","variants":{"managers":{"problem":"مدیر سایت مسئول آماده‌بودن ناوگان شناخته می‌شود، اما برای هر هزینه کوچک باید چند تأیید بگیرد. از طرف دیگر، مدیر دیگری خارج از اختیار قولی به مشتری می‌دهد که منابع آن فراهم نیست. در هر دو حالت، نتیجه و اختیار هم‌تراز نیستند.","analysis":["ممکن است مسئولیت نتیجه را واگذار کنیم، اما حق انتخاب را همچنان برای خود نگه داریم.","اگر تصمیم کارکنان را پس از نتیجه و با معیار تازه قضاوت کنیم، آنان یاد می‌گیرند همیشه منتظر بمانند.","واگذاری بدون بررسی آمادگی و حمایت هم می‌تواند اضطراب و احساس رهاشدگی بسازد."],"lesson":"پاسخ‌گویی منصفانه از توافق قبلی درباره انتظار، اختیار، حمایت و معیار گفت‌وگو شروع می‌شود.","note":"بعد از نتیجه، قواعد بازی را یک‌طرفه عوض نکنید.","solution":["با مسئول هر کار جداگانه گفت‌وگو کنید و از او بخواهید مسئولیت و اختیارش را با زبان خودش توضیح دهد.","تفاوت برداشت‌ها را پیش از ارزیابی روشن کنید و بپرسید چه حمایتی لازم دارد.","هنگام مرور تصمیم، اطلاعات و اختیار در دسترس فرد را هم ببینید؛ فقط نتیجه نهایی را مبنای قضاوت نگذارید.","برای تصمیم مسئولانه و توضیح صادقانه بازخورد بدهید؛ اختیار را با نخستین نتیجه نامطلوب خودکار پس نگیرید."],"questions":["آیا از فرد نتیجه‌ای می‌خواهیم که امکان اثرگذاری کافی بر آن ندارد؟","کدام واکنش ما افراد را به انتظار دائمی عادت داده است؟"],"dialogue":"قبل از اینکه نتیجه را ارزیابی کنیم، می‌خواهم روشن باشد چه اختیاری داشتی و چه حمایتی از من لازم بود."},"hq":{"problem":"سایت از شما می‌خواهد یک هزینه یا تغییر برنامه را تأیید کنید. قبلاً چنین کارهایی را هماهنگ کرده‌اید، اما روشن نیست اختیار تأیید هم دارید یا فقط مسئول پیگیری هستید. نمی‌خواهید کار متوقف بماند یا تعهد بدون مجوز ایجاد شود.","analysis":["وقتی انتظار و حق تصمیم روشن نیست، ممکن است برای محافظت از خود هیچ کاری نکنیم.","گاهی هم برای نشان‌دادن کارآمدی، وعده‌ای می‌دهیم که در اختیار ما نیست.","هر دو رفتار می‌تواند از ترس قضاوت یا ابهام نقش بیاید؛ باید انتظار را در گفت‌وگو روشن کرد."],"lesson":"مسئولیت‌پذیری یعنی در بخش در اختیار خود فعال باشید و بخش نیازمند تصمیم دیگری را روشن مطرح کنید.","note":"کمک‌خواستن با کنارکشیدن از مسئولیت یکسان نیست.","solution":["با سرپرست درباره یک کار واقعی بپرسید: «کدام بخش را خودم تصمیم بگیرم و کجا با شما مشورت کنم؟»","برداشت خود را بازگو کنید تا توافق دوطرفه باشد.","در پیگیری، سهم انجام‌شده خود و تصمیم لازم از دیگری را بدون سرزنش توضیح دهید.","اگر نتیجه مطلوب نبود، سهم خود را بپذیرید و درباره یادگیری و حمایت مورد نیاز صحبت کنید."],"questions":["کجا از ترس اشتباه، داخل اختیار خود هم اقدام نمی‌کنیم؟","چگونه مسئولیت خود را بپذیریم بدون اینکه اختیار نداشته را ادعا کنیم؟"],"dialogue":"این بخش را خودم پیگیری می‌کنم؛ برای این تصمیم به روشن‌شدن اختیار و نظر شما نیاز دارم."},"operations":{"problem":"در مسیر کار، وضعیت با برنامه فرق کرده است. می‌توانید بخشی از کار عادی را طبق آموزش انجام دهید، اما تغییر مقصد یا دستکاری فنی خارج از اختیار شماست. نگرانید پرسیدن، نشانه ناتوانی تلقی شود.","analysis":["ممکن است ندانیم چه چیزی از ما انتظار می‌رود، اما برای کم‌تجربه دیده‌نشدن سؤال نکنیم.","ترس از سرزنش می‌تواند باعث انتظار زیاد یا اقدام عجولانه شود.","سرپرست با توضیح روشن و پاسخ محترمانه می‌تواند این دو واکنش را کمتر کند."],"lesson":"انتظار و حد کار خود را روشن بپرسید؛ نه بی‌دلیل کنار بکشید و نه خارج از صلاحیت قول بدهید.","note":"ابهام را گفتن، بهتر از پنهان‌کردن آن است.","solution":["پیش از کار بگویید از شما چه خواسته شده و کدام بخش هنوز روشن نیست.","اگر شرایط عوض شد، واقعیت را توضیح دهید و برای انتظار تازه سؤال کنید.","در محدوده روشن کار مسئولانه همکاری کنید و کمک لازم را مشخص بخواهید.","در مرور نتیجه، سهم خود را بپذیرید و بگویید برای دفعه بعد چه توضیح یا حمایتی لازم دارید."],"questions":["از چه سؤالی خجالت می‌کشیم که برای کار ضروری است؟","برای روشن‌شدن انتظار، از سرپرست چه می‌خواهیم؟"],"dialogue":"می‌خواهم مسئولیت خودم را درست انجام بدهم؛ لطفاً روشن کنید در این شرایط تا کجا اختیار دارم."}},"theory":{"name":"ابهام نقش و توانمندسازی روان‌شناختی","explanation":"فرد باید بداند چه انتظاری از او می‌رود و کجا حق انتخاب دارد. احساس اثرگذاری بدون اختیار و حمایت متناسب دشوار است؛ اختیار هم مسئولیت توضیح‌دادن تصمیم و یادگیری از نتیجه را حذف نمی‌کند.","source":"role","secondary":"empowerment"}},{"id":15,"title":"یک کار، دو تیم؛ مسئول واقعی کیست؟","concept":"مسئولیت مشترک و تحویل روشن","evidence":"هر تیم پایان مسئولیت خود را کجا می‌بیند؟ آیا از پذیرش طرف بعد مطمئن می‌شود یا با گفتن «من فرستادم» کنار می‌کشد؟","variants":{"managers":{"problem":"تعمیرات اعلام می‌کند کار خودرو تمام شده است؛ عملیات تصور می‌کند مجوز آماده‌به‌کاری هم صادر شده و ستاد زمان مأموریت را قطعی می‌کند. بعد معلوم می‌شود یک تأیید و هماهنگی مقصد باقی مانده است. هر تیم پایان کار خودش را پایان کل فرایند دانسته است.","analysis":["اگر هر واحد فقط تمام‌شدن سهم خودش را موفقیت بداند، نیاز نفر بعد نادیده می‌ماند.","ممکن است مسئولیت کار مشترک را «همه» بدانیم، اما در عمل هیچ‌کس گفت‌وگو را تا نتیجه دنبال نکند.","سرزنش پس از مشکل، واحدها را به دفاع از خود و جمع‌کردن دلیل علیه دیگری سوق می‌دهد."],"lesson":"مسئولیت مشترک باید به تعهد روشن هر طرف و توجه به نیاز نفر بعد تبدیل شود.","note":"به جای پیدا کردن مقصر، ابتدا شکاف انتظارها را پیدا کنید؛ مسئولیت فردی هم باید منصفانه بررسی شود.","solution":["دو طرف از زبان خود بگویند چه چیزی را پایان مسئولیتشان می‌دانند و از طرف مقابل چه انتظاری دارند.","روی رفتار تحویل توافق کنید: روشن‌گفتن کار باقی‌مانده، اطمینان از فهم نفر بعد و پیگیری ابهام.","از فردی که فراتر از مرز واحد به حل نتیجه مشترک کمک کرده قدردانی کنید؛ همکاری را به تصاحب اختیار دیگران تبدیل نکنید.","پس از یک مسئله مشترک، گفت‌وگو را با «هر کدام چه چیزی را می‌توانستیم روشن‌تر کنیم؟» شروع کنید."],"questions":["آیا موفقیت را از نگاه واحد خود می‌بینیم یا گیرنده نهایی کار؟","چه رفتاری باعث می‌شود مسئولیت بین دو تیم معلق بماند؟"],"dialogue":"قبل از اینکه بگوییم تقصیر کدام واحد بود، روشن کنیم هر طرف چه انتظاری داشت و کجا این انتظار منتقل نشد."},"hq":{"problem":"اسناد را برای همکار واحد دیگر می‌فرستید و کار را انجام‌شده علامت می‌زنید. او پیام را ندیده یا یک مدرک کم دارد. سایت منتظر نتیجه است و هر دو واحد می‌گویند نوبت طرف دیگر بوده است.","analysis":["ارسال کار می‌تواند در ما احساس پایان وظیفه بسازد، حتی وقتی نفر بعد نیاز را نفهمیده است.","ترس از دخالت در کار دیگری ممکن است مانع پیگیری محترمانه شود.","وقتی مشکل پیش می‌آید، دفاع «من که فرستادم» یادگیری مشترک را متوقف می‌کند."],"lesson":"تحویل حرفه‌ای یعنی توجه به فهم و نیاز نفر بعد، نه صرفاً کنارگذاشتن کار از میز خود.","note":"پیگیری محترمانه را با دخالت اشتباه نگیرید.","solution":["هنگام تحویل بگویید چه انجام شده و از طرف مقابل چه انتظار دارید.","از او بخواهید اگر چیزی ناقص یا مبهم است بگوید؛ سؤال او را مزاحمت تلقی نکنید.","تا وقتی برداشت مشترک شکل نگرفته، از عبارت «دیگر به من مربوط نیست» فاصله بگیرید.","اگر تحویل ناموفق بود، سهم خود را بپذیرید و درباره رفتار بهتر برای دفعه بعد توافق کنید."],"questions":["آیا مطمئنیم طرف مقابل همان چیزی را فهمیده که ما منظور داشته‌ایم؟","کدام جمله ما همکاری در نقطه تحویل را قطع می‌کند؟"],"dialogue":"این بخش انجام شده و این مورد باقی مانده؛ می‌خواهم مطمئن شوم انتظار قدم بعدی برای هر دومان روشن است."},"operations":{"problem":"شیفت شما تمام شده و خودرو یا کار نیمه‌تمام را به گروه بعد می‌دهید. می‌گویید: «همه چیز را به دفتر گفته‌ام.» گروه بعد نمی‌داند چه کاری باقی مانده و کدام وضعیت هنوز نیاز به تعیین تکلیف دارد.","analysis":["در پایان شیفت ممکن است عجله کنیم و فرض کنیم نفر بعد خودش همه چیز را می‌فهمد.","خجالت از توضیح دوباره یا نخواستنِ مسئولیت بیشتر می‌تواند تحویل را ناقص کند.","نفر بعد هم ممکن است برای باتجربه دیده‌شدن، ابهامش را نپرسد."],"lesson":"کار را طوری تحویل دهید که نفر بعد بداند چه شده و چه چیزی هنوز نیاز به پیگیری دارد.","note":"فهم نفر بعد را فرض نکنید؛ از او بپرسید.","solution":["با حوصله وضعیت و کار باقی‌مانده را به همکار بعدی توضیح دهید.","بپرسید چه چیزی هنوز برای او روشن نیست و از سؤالش استقبال کنید.","اگر خودتان گیرنده هستید، برای فهمیدن دوباره بپرسید؛ ادعای دانستن نکنید.","اگر بعداً فهمیدید نکته‌ای را نگفته‌اید، خودتان خبر بدهید و در اصلاح آن همکاری کنید."],"questions":["چه چیزی باعث می‌شود تحویل شیفت را با عجله انجام بدهیم؟","اگر بعد از رفتن متوجه شویم نکته‌ای را نگفته‌ایم، رفتار مسئولانه چیست؟"],"dialogue":"این قسمت انجام شده و این موضوع هنوز مانده؛ چه چیزی را بیشتر توضیح بدهم تا کار برایت روشن باشد؟"}},"theory":{"name":"وضوح نقش و وابستگی متقابل هدف‌ها","explanation":"در کار مشترک، ابهام درباره سهم افراد می‌تواند مسئولیت را بین آنان معلق کند. روشن‌شدن انتظار هر طرف، همراه با توجه به نتیجه مشترک، مبنایی برای گفت‌وگو درباره همکاری فراهم می‌کند.","source":"role","secondary":"cooperation"}}];
